<script setup lang="ts">
import { onMounted,reactive,ref,watch } from 'vue'; import { ElMessage } from 'element-plus'; import { api } from '../api'; import type { Connection } from '../types'
const items=ref<Connection[]>([]),open=ref(false),editing=ref<Connection>(),testing=ref('')
const providers=[['daji','大吉找源'],['elim','Elim 找源'],['alibaba','1688 开放平台'],['oss','阿里云 OSS'],['ai_chat','AI 文案'],['ai_image','AI 图片'],['hicustom','HICUSTOM'],['s2b','S2B'],['sds','SDS'],['tms','TMS']]
const form=reactive<any>({provider:'daji',name:'',base_url:'',model:'',enabled:true,key1:'',key2:'',configText:'{}'})
const aiDefaults:any={ai_chat:{name:'OpenAI 官方文案/视觉',base_url:'https://api.openai.com/v1/chat/completions',config:{models:[],default_model:''}},ai_image:{name:'OpenAI 官方生图',base_url:'https://api.openai.com/v1/images/edits',config:{models:[],default_model:''}}}
const isAi=()=>['ai_chat','ai_image'].includes(form.provider)
watch(()=>form.provider,(provider)=>{const preset=aiDefaults[provider];if(preset&&!editing.value)Object.assign(form,{name:preset.name,base_url:preset.base_url,model:preset.config.default_model,configText:JSON.stringify(preset.config,null,2)})})
function secretNames(){if(['daji','alibaba'].includes(form.provider))return ['app_key','app_secret'];if(form.provider==='oss')return ['access_key_id','access_key_secret'];return ['api_key','']}
async function load(){items.value=(await api.get<any>('/connections')).items} function add(){editing.value=undefined;Object.assign(form,{provider:'ai_chat',name:aiDefaults.ai_chat.name,base_url:aiDefaults.ai_chat.base_url,model:aiDefaults.ai_chat.config.default_model,enabled:true,key1:'',key2:'',configText:JSON.stringify(aiDefaults.ai_chat.config,null,2)});open.value=true}
function edit(x:Connection){editing.value=x;Object.assign(form,{...x,model:String(x.config?.default_model||x.config?.model||aiDefaults[x.provider]?.config?.default_model||''),key1:'',key2:'',configText:JSON.stringify(x.config||{},null,2)});open.value=true}
async function save(){let config;try{config=JSON.parse(form.configText||'{}')}catch{return ElMessage.error('功能参数格式不正确')};if(isAi()){const model=String(form.model||'').trim();if(!model)return ElMessage.warning('请填写模型名称');config={...config,default_model:model,models:Array.from(new Set([model,...((config.models||[]) as string[])]))}}const [a,b]=secretNames(),secrets:any={};if(form.key1)secrets[a]=form.key1;if(b&&form.key2)secrets[b]=form.key2;const body={provider:form.provider,name:form.name,base_url:form.base_url,enabled:form.enabled,config,secrets};try{editing.value?await api.patch(`/connections/${editing.value.id}`,body):await api.post('/connections',body);open.value=false;ElMessage.success('接口已保存');await load()}catch(error:any){const message=error?.response?.data?.message||error?.message||'接口保存失败';ElMessage.error(message)}}
async function test(x:Connection){testing.value=x.id;try{await api.post(`/connections/${x.id}/test`);ElMessage.success('配置检查通过')}finally{testing.value=''}} onMounted(load)
</script>
<template><div class="panel"><div class="panel-head"><div><h2>接口中心</h2><p>密钥加密保存，页面与日志均不返回明文</p></div><el-button type="primary" @click="add">添加接口</el-button></div><el-table :data="items"><el-table-column prop="provider" label="类型" width="130"/><el-table-column prop="name" label="名称" min-width="180"/><el-table-column prop="base_url" label="地址" min-width="260" show-overflow-tooltip/><el-table-column label="状态" width="120"><template #default="s"><el-tag :type="s.row.status==='failed'?'danger':s.row.status==='configured'?'success':'info'">{{s.row.status||'未测试'}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="s"><el-button link @click="edit(s.row)">编辑</el-button><el-button link type="primary" :loading="testing===s.row.id" @click="test(s.row)">检查配置</el-button></template></el-table-column></el-table>
<el-dialog v-model="open" :title="editing?'编辑接口':'添加接口'" width="620"><el-form label-width="110"><el-form-item label="接口类型"><el-select v-model="form.provider" :disabled="!!editing"><el-option v-for="p in providers" :key="p[0]" :label="p[1]" :value="p[0]"/></el-select></el-form-item><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="接口地址"><el-input v-model="form.base_url" placeholder="可使用服务默认地址"/></el-form-item><el-form-item v-if="isAi()" label="模型"><el-select v-model="form.model" filterable allow-create default-first-option placeholder="填写该服务账户实际可用的模型名称" style="width:100%"><el-option v-for="model in ((JSON.parse(form.configText||'{}').models)||[])" :key="model" :label="model" :value="model"/></el-select></el-form-item><el-form-item v-if="!isAi()" label="功能参数"><el-input v-model="form.configText" type="textarea" :rows="6"/></el-form-item><el-form-item :label="isAi()?'API Key':secretNames()[0]"><el-input v-model="form.key1" type="password" show-password :placeholder="editing?'留空表示不修改':'只需粘贴 API Key'"/></el-form-item><el-form-item v-if="secretNames()[1]" :label="secretNames()[1]"><el-input v-model="form.key2" type="password" show-password/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
